,"","--","-- Chỉ mục cho bảng `event_attendance`","--","ALTER TABLE `event_attendance`","  ADD PRIMARY KEY (`attendance_id`),","  ADD UNIQUE KEY `event_id` (`event_id`,`user_id`),","  ADD KEY `fk_attendance_member` (`user_id`);","","--","-- Chỉ mục cho bảng `financials`","--","ALTER TABLE `financials`","  ADD PRIMARY KEY (`transaction_id`),","  ADD KEY `fk_financials_users` (`created_by`),","  ADD KEY `fk_financials_events` (`reference_event_id`);","","--","-- Chỉ mục cho bảng `members`","--","ALTER TABLE `members`","  ADD PRIMARY KEY (`user_id`),","  ADD KEY `fk_members_departments` (`department_id`);","","--","-- Chỉ mục cho bảng `roles`","--","ALTER TABLE `roles`","  ADD PRIMARY KEY (`role_id`),","  ADD UNIQUE KEY `role_name` (`role_name`);","","--","-- Chỉ mục cho bảng `users`","--","ALTER TABLE `users`","  ADD PRIMARY KEY (`id`),","  ADD KEY `role` (`role`);","","--","-- AUTO_INCREMENT cho các bảng đã đổ","--","","--","-- AUTO_INCREMENT cho bảng `announcements`","--","ALTER TABLE `announcements`","  MODIFY `announcement_id` int(11) NOT NULL AUTO_INCREMENT;","","--","-- AUTO_INCREMENT cho bảng `departments`","--","ALTER TABLE `departments`","  MODIFY `department_id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=6;","","--","-- AUTO_INCREMENT cho bảng `events`","--","ALTER TABLE `events`","  MODIFY `event_id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=6;","","--","-- AUTO_INCREMENT cho bảng `event_attendance`","--","ALTER TABLE `event_attendance`","  MODIFY `attendance_id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=2;","","--","-- AUTO_INCREMENT cho bảng `financials`","--","ALTER TABLE `financials`","  MODIFY `transaction_id` int(11) NOT NULL AUTO_INCREMENT;","","--","-- AUTO_INCREMENT cho bảng `roles`","--","ALTER TABLE `roles`","  MODIFY `role_id` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=4;","","--","-- Các ràng buộc cho các bảng đã đổ","--","","--","-- Các ràng buộc cho bảng `announcements`","--","ALTER TABLE `announcements`","  ADD CONSTRAINT `announcements_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`);","","--","-- Các ràng buộc cho bảng `events`","--","ALTER TABLE `events`","  ADD CONSTRAINT `events_ibfk_1` FOREIGN KEY (`host_by`) REFERENCES `users` (`id`);","","--","-- Các ràng buộc cho bảng `event_attendance`","--","ALTER TABLE `event_attendance`","  ADD CONSTRAINT `fk_attendance_event` FOREIGN KEY (`event_id`) REFERENCES `events` (`event_id`) ON DELETE CASCADE ON UPDATE CASCADE,","  ADD CONSTRAINT `fk_attendance_member` FOREIGN KEY (`user_id`) REFERENCES `members` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE;","","--","-- Các ràng buộc cho bảng `financials`","--","ALTER TABLE `financials`","  ADD CONSTRAINT `fk_financials_events` FOREIGN KEY (`reference_event_id`) REFERENCES `events` (`event_id`) ON DELETE SET NULL ON UPDATE CASCADE,","  ADD CONSTRAINT `fk_financials_users` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE;","","--","-- Các ràng buộc cho bảng `members`","--","ALTER TABLE `members`","  ADD CONSTRAINT `fk_members_departments` FOREIGN KEY (`department_id`) REFERENCES `departments` (`department_id`) ON DELETE CASCADE ON UPDATE SET NULL,","  ADD CONSTRAINT `members_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`);","","--","-- Các ràng buộc cho bảng `roles`","--","ALTER TABLE `roles`","  ADD CONSTRAINT `roles_ibfk_1` FOREIGN KEY (`role_id`) REFERENCES `users` (`id`);","COMMIT;","","/*!40101 SET CHARACTER_SET_CLIENT=@OLD_CHARACTER_SET_CLIENT */;","/*!40101 SET CHARACTER_SET_RESULTS=@OLD_CHARACTER_SET_RESULTS */;","/*!40101 SET COLLATION_CONNECTION=@OLD_COLLATION_CONNECTION */;"],"stylingDirectives":null,"colorizedLines":["\u003cspan class=\"pl-c\"\u003e\u003cspan class=\"pl-c\"\u003e--\u003c/span\u003e phpMyAdmin SQL Dump\u003c/span\u003e","\u003cspan class=\"pl-c\"\u003e\u003cspan class=\"pl-c\"\u003e--\u003c/span\u003e version 5.2.1\u003c/span\u003e","\u003cspan class=\"pl-c\"\u003e\u003cspan class=\"pl-c\"\u003e--\u0